    std::string_view view() const { return {}; }
    bool operator==(std::string_view other) const { return false; }
};

solution.solution.cpp:
#include <algorithm>
#include <cstddef>
#include <cstring>
#include <string_view>
#include <utility>

class SmallString
{
public:
    static constexpr std::size_t INLINE_CAPACITY{ 15 };

    SmallString() { local[0] = '\0'; }

    SmallString(const char* text) : SmallString() { append(text); }

    ~SmallString() { if (heap) delete[] heap; }

    SmallString(const SmallString& other) : SmallString() { append(other.view()); }

    SmallString(SmallString&& other) noexcept : SmallString()
    {
        if (other.heap)
        {
            heap = other.heap;
            length = other.length;
            heapCapacity = other.heapCapacity;
            other.heap = nullptr;
            other.heapCapacity = 0;
        }
        else
        {
            std::memcpy(local, other.local, other.length + 1);
            length = other.length;
        }
        other.length = 0;
        other.local[0] = '\0';
    }

    SmallString& operator=(SmallString other) noexcept
    {
        swap(*this, other);
        return *this;
    }

    friend void swap(SmallString& a, SmallString& b) noexcept
    {
        SmallString temp{ std::move(a) };
        a.takeFrom(b);
        b.takeFrom(temp);
    }

    void append(std::string_view more)
    {
        const std::size_t needed{ length + more.size() };
        if (needed > capacity())
        {
            const std::size_t newCapacity{ std::max(2 * capacity(), needed) };
            char* block{ new char[newCapacity + 1] };
            std::memcpy(block, c_str(), length);
            if (heap) delete[] heap;
            heap = block;
            heapCapacity = newCapacity;
        }
        char* text{ heap ? heap : local };
        std::memcpy(text + length, more.data(), more.size());
        length = needed;
        text[length] = '\0';
    }

    std::size_t size() const { return length; }
    std::size_t capacity() const { return heap ? heapCapacity : INLINE_CAPACITY; }
    bool isInline() const { return heap == nullptr; }
    const char* c_str() const { return heap ? heap : local; }
    std::string_view view() const { return { c_str(), length }; }
    bool operator==(std::string_view other) const { return view() == other; }

private:
    char local[INLINE_CAPACITY + 1];
    char* heap{ nullptr };
    std::size_t length{ 0 };
    std::size_t heapCapacity{ 0 };

    // Takes over other's contents (as a move would) after freeing our own.
    void takeFrom(SmallString& other) noexcept
    {
        if (heap) delete[] heap;
        heap = nullptr;
        heapCapacity = 0;
        if (other.heap)
        {
            heap = other.heap;
            heapCapacity = other.heapCapacity;
            other.heap = nullptr;
            other.heapCapacity = 0;
        }
        else std::memcpy(local, other.local, other.length + 1);
        length = other.length;
        other.length = 0;
        other.local[0] = '\0';
    }
};

unitTests:
#include <cstdlib>
#include <new>
#include <string>
static int liveArrays{ 0 };
void* operator new[](std::size_t size) { ++liveArrays; if (void* p{ std::malloc(size ? size : 1) }) return p; throw std::bad_alloc{}; }
void operator delete[](void* p) noexcept { if (p) { --liveArrays; std::free(p); } }
void operator delete[](void* p, std::size_t) noexcept { if (p) { --liveArrays; std::free(p); } }
static bool inside(const SmallString& s) { const char* p{ s.c_str() }; const char* o{ reinterpret_cast<const char*>(&s) }; return p >= o && p < o + sizeof(s); }

TEST("short strings stay inside the object") {
    const int before{ liveArrays };
    SmallString empty;
    CHECK_EQ(empty.size(), 0u); CHECK_EQ(std::string(empty.c_str()), std::string(""));
    SmallString s{ "hello" };
    CHECK(s.isInline()); CHECK(inside(s));
    CHECK(s == "hello");
    SmallString full{ "fifteen chars!!" };
    CHECK_EQ(full.size(), 15u); CHECK(full.isInline());
    CHECK_EQ(liveArrays, before);
}
TEST("long strings use one heap block") {
    const int before{ liveArrays };
    {
        SmallString s{ "sixteen chars!!!" };
        CHECK(!s.isInline()); CHECK(!inside(s));
        CHECK_EQ(s.size(), 16u);
        CHECK(s == "sixteen chars!!!");
        CHECK_EQ(liveArrays, before + 1);
    }
    CHECK_EQ(liveArrays, before);
}
TEST("append grows geometrically") {
    const int before{ liveArrays };
    {
        SmallString s{ "0123456789" };
        s.append("abcde");
        CHECK(s.isInline());
        s.append("X");
        CHECK(!s.isInline());
        CHECK_EQ(s.capacity(), 30u);
        CHECK(s == "0123456789abcdeX");
        for (int i{ 0 }; i < 100; ++i) s.append("y");
        CHECK_EQ(s.size(), 116u);
        CHECK_EQ(s.c_str()[116], '\0');
        CHECK(s.capacity() >= 116u);
        CHECK_EQ(liveArrays, before + 1);
        s.append(std::string(500, 'z'));
        CHECK_EQ(s.size(), 616u);
        CHECK_EQ(s.capacity(), 616u);
    }
    CHECK_EQ(liveArrays, before);
}
TEST("copies") {
    const int before{ liveArrays };
    {
        SmallString shortOne{ "abc" };
        SmallString copy{ shortOne };
        CHECK(copy == "abc"); CHECK(copy.isInline()); CHECK(inside(copy));
        SmallString longOne{ "a string that is longer than fifteen" };
        SmallString longCopy{ longOne };
        CHECK(longCopy == longOne.view());
        CHECK(longCopy.c_str() != longOne.c_str());
        longCopy.append("!");
        CHECK(longOne == "a string that is longer than fifteen");
        CHECK_EQ(liveArrays, before + 2);
    }
    CHECK_EQ(liveArrays, before);
}
TEST("moves and assignment") {
    const int before{ liveArrays };
    {
        SmallString a{ "a string that is longer than fifteen" };
        const char* block{ a.c_str() };
        SmallString b{ std::move(a) };
        CHECK(b.c_str() == block);
        CHECK(a.isInline()); CHECK_EQ(a.size(), 0u);
        SmallString c{ "tiny" };
        SmallString d{ std::move(c) };
        CHECK(d == "tiny"); CHECK(inside(d));
        c = b;
        CHECK(c == b.view());
        c = "short";
        CHECK(c == "short"); CHECK(c.isInline());
        SmallString& alias{ b };
        b = alias;
        CHECK(b == "a string that is longer than fifteen");
        const char* current{ b.c_str() };
        d = std::move(b);
        CHECK(d.c_str() == current);
        CHECK_EQ(liveArrays, before + 1);
    }
    CHECK_EQ(liveArrays, before);
}

